sys_variable_value.value:
(function(outputs, steps, stepResult, assertEqual)
{
	var test = new x_snc_devtools.TestAPI(outputs, steps, stepResult, assertEqual);
	
	test.SetResult(true);
	
	function TestCase_TableCreate(vScope,strName,strLabel,strParentTable,vExpected)
	{
		function TestCase_TableCreate_CheckResult(vInput,vExpected,vResult)
		{
			if (vExpected == false)
			{
				return (vExpected == vResult);
			}
			if (IsValidSysId(vResult) == false)
			{
				return false;
			}
			var grTable = GetTableRecord(vResult);
			if (IsValidRecord(grTable) == false)
			{
				return false;
			}
			strParentTable = GetStringValue(strParentTable);
			if (strParentTable != '')
			{
				if (IsDerivedFromTable(grTable.name,strParentTable) == false)
				{
					return false;
				}
			}
			return true;
		}
		
		test.TestCase(
			'Function TableCreate()',
			TableCreate,
			{
				'vScope': vScope,
				'strName': strName,
				'strLabel': strLabel,
				'strParentTable': strParentTable
			},
			vExpected,
			TestCase_TableCreate_CheckResult);
	}
		
	TestCase_TableCreate(null,null,null,null,false);

	TestCase_TableCreate('global','test_my_table','Test My Table','',true);
	TestCase_TableCreate('global','test_my_process','Test My Process','task',true);

	var strAppSysId = AppCreate('Test Alpha','scoped','x_test_alpha');

	TestCase_TableCreate(strAppSysId,'test_my_table','Test My Table (Scoped)','',true);
	TestCase_TableCreate(strAppSysId,'test_my_process','Test My Process (Scoped)','task',true);


	return test.GetResult();
	
})(outputs, steps, stepResult, assertEqual);
